import java.io.BufferedInputStream

private const val MOD = 998244353L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= length) {
            length = input.read(buffer)
            ptr = 0
            if (length <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun next(): String {
        val sb = StringBuilder()
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c >= 0)
        while (c > 32) {
            sb.append(c.toChar())
            c = readByte()
        }
        return sb.toString()
    }

    fun nextInt(): Int = next().toInt()
    fun nextLong(): Long = next().toLong()
}

private data class Option(val ch: Int, val to: Int)
private data class Edge(val to: Int, val weight: Int)

private fun modPow(baseValue: Long, exponentValue: Long): Long {
    var base = baseValue
    var exponent = exponentValue
    var result = 1L
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) result = result * base % MOD
        base = base * base % MOD
        exponent = exponent shr 1
    }
    return result
}

private fun berlekampMassey(sequence: LongArray): LongArray {
    val size = sequence.size
    var c = LongArray(size + 1)
    var bPoly = LongArray(size + 1)
    c[0] = 1L
    bPoly[0] = 1L

    var cMax = 0
    var bMax = 0
    var length = 0
    var shift = 1
    var lastDiscrepancy = 1L

    for (position in sequence.indices) {
        var discrepancy = 0L
        for (i in 0..length) {
            discrepancy = (discrepancy + c[i] * sequence[position - i]) % MOD
        }

        if (discrepancy == 0L) {
            shift++
            continue
        }

        val oldC = c.copyOf()
        val oldCMax = cMax
        val factor = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD

        for (i in 0..bMax) {
            val index = i + shift
            var value = c[index] - factor * bPoly[i] % MOD
            if (value < 0) value += MOD
            c[index] = value
            if (value != 0L && index > cMax) cMax = index
        }

        if (2 * length <= position) {
            length = position + 1 - length
            bPoly = oldC
            bMax = oldCMax
            lastDiscrepancy = discrepancy
            shift = 1
        } else {
            shift++
        }
    }

    val recurrence = LongArray(length)
    for (i in 0 until length) {
        recurrence[i] = if (c[i + 1] == 0L) 0L else MOD - c[i + 1]
    }
    return recurrence
}

private fun combinePolynomials(
    a: LongArray,
    b: LongArray,
    recurrence: LongArray
): LongArray {
    val length = recurrence.size
    val product = LongArray(2 * length - 1)

    for (i in 0 until length) {
        if (a[i] == 0L) continue
        for (j in 0 until length) {
            if (b[j] == 0L) continue
            product[i + j] = (product[i + j] + a[i] * b[j]) % MOD
        }
    }

    for (degree in 2 * length - 2 downTo length) {
        val value = product[degree]
        if (value == 0L) continue
        for (j in 1..length) {
            val index = degree - j
            product[index] = (product[index] + value * recurrence[j - 1]) % MOD
        }
    }

    return product.copyOf(length)
}

private fun linearRecurrenceNth(
    initial: LongArray,
    recurrence: LongArray,
    index: Long
): Long {
    if (index < initial.size) return initial[index.toInt()]

    val length = recurrence.size
    if (length == 0) return 0L

    var result = LongArray(length)
    result[0] = 1L

    var base = LongArray(length)
    if (length == 1) {
        base[0] = recurrence[0]
    } else {
        base[1] = 1L
    }

    var exponent = index
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = combinePolynomials(result, base, recurrence)
        }
        exponent = exponent shr 1
        if (exponent > 0) {
            base = combinePolynomials(base, base, recurrence)
        }
    }

    var answer = 0L
    for (i in 0 until length) {
        answer = (answer + result[i] * initial[i]) % MOD
    }
    return answer
}

