    for (id in 0 until statusCount) {
        val suffix = statuses[id]
        if (suffix.isNotEmpty()) {
            options[id].add(
                Option(
                    suffix[0] - 'a',
                    statusId[suffix.substring(1)]!!
                )
            )
        } else {
            for (word in words) {
                options[id].add(
                    Option(
                        word[0] - 'a',
                        statusId[word.substring(1)]!!
                    )
                )
            }
        }
    }

    val totalPairs = statusCount * statusCount
    val allEdges = arrayOfNulls<MutableList<Edge>>(totalPairs)
    val reachable = BooleanArray(totalPairs)
    val queue = IntArray(totalPairs)
    var head = 0
    var tail = 0

    val startOld = 0
    reachable[startOld] = true
    queue[tail++] = startOld

