                        found = i
                        break
                    }
                }

                if (found >= 0) {
                    weights[found]++
                } else {
                    destinations[edgeCount] = destination
                    weights[edgeCount] = 1
                    edgeCount++
                }
            }
        }

        val list = ArrayList<Edge>(edgeCount)
        for (i in 0 until edgeCount) {
            val destination = destinations[i]
            list.add(Edge(destination, weights[i]))
            if (!reachable[destination]) {
                reachable[destination] = true
                queue[tail++] = destination
            }
        }
        allEdges[state] = list
    }

    val reverse = arrayOfNulls<MutableList<Int>>(totalPairs)
    for (state in 0 until totalPairs) {
        if (!reachable[state]) continue
        for (edge in allEdges[state] ?: emptyList()) {
            var list = reverse[edge.to]
            if (list == null) {
                list = ArrayList()
                reverse[edge.to] = list
            }
            list.add(state)
        }
    }

    val canReturn = BooleanArray(totalPairs)
    head = 0
    tail = 0
    canReturn[startOld] = true
    queue[tail++] = startOld

