        for (previous in reverse[state] ?: emptyList()) {
            if (!canReturn[previous]) {
                canReturn[previous] = true
                queue[tail++] = previous
            }
        }
    }

    val newId = IntArray(totalPairs) { -1 }
    var stateCount = 0
    for (state in 0 until totalPairs) {
        if (reachable[state] && canReturn[state]) {
            newId[state] = stateCount++
        }
    }

    val graph = Array(stateCount) { ArrayList<Edge>() }
    for (oldState in 0 until totalPairs) {
        val from = newId[oldState]
        if (from < 0) continue
        for (edge in allEdges[oldState] ?: emptyList()) {
            val to = newId[edge.to]
            if (to >= 0) graph[from].add(Edge(to, edge.weight))
        }
    }

    val start = newId[startOld]
    val termCount = 2 * stateCount + 5
    val sequence = LongArray(termCount)
    var current = LongArray(stateCount)
    current[start] = 1L

    for (step in 0 until termCount) {
        sequence[step] = current[start]

        val next = LongArray(stateCount)
        for (state in 0 until stateCount) {
            val value = current[state]
            if (value == 0L) continue
            for (edge in graph[state]) {
                next[edge.to] =
                    (next[edge.to] + value * edge.weight.toLong()) % MOD
            }
        }
        current = next
    }

    if (m < sequence.size) {
        println(sequence[m.toInt()])
        return
    }

    val recurrence = berlekampMassey(sequence)
    val initial = sequence.copyOf(recurrence.size)
    println(linearRecurrenceNth(initial, recurrence, m))
}

