import java.io.BufferedInputStream

private const val MOD = 998244353L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun next(): String {
        val result = StringBuilder()
        var c: Int
        do {
            c = readByte()
        } while (c <= 32 && c >= 0)
        while (c > 32 && c >= 0) {
            result.append(c.toChar())
            c = readByte()
        }
        return result.toString()
    }

    fun nextInt(): Int = next().toInt()
    fun nextLong(): Long = next().toLong()
}

private data class State(val side: Int, val residual: String)
private data class Edge(val to: Int, val weight: Int)

private fun modPow(baseValue: Long, exponentValue: Long): Long {
    var base = baseValue
    var exponent = exponentValue
    var result = 1L
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) result = result * base % MOD
        base = base * base % MOD
        exponent = exponent shr 1
    }
    return result
}

private fun berlekampMassey(sequence: LongArray): LongArray {
    var c = mutableListOf(1L)
    var b = mutableListOf(1L)
    var length = 0
    var shift = 1
    var lastDiscrepancy = 1L

    for (n in sequence.indices) {
        var discrepancy = sequence[n]
        for (i in 1..length) {
            discrepancy = (discrepancy + c[i] * sequence[n - i]) % MOD
        }

        if (discrepancy == 0L) {
            shift++
            continue
        }

        val oldC = c.toMutableList()
        val coefficient = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD

        while (c.size < b.size + shift) c.add(0L)
        for (i in b.indices) {
            val index = i + shift
            c[index] = (c[index] - coefficient * b[i]) % MOD
            if (c[index] < 0) c[index] += MOD
        }

        if (2 * length <= n) {
            length = n + 1 - length
            b = oldC
            lastDiscrepancy = discrepancy
            shift = 1
        } else {
            shift++
        }
    }

    return LongArray(length) { i ->
        if (c[i + 1] == 0L) 0L else MOD - c[i + 1]
    }
}

private fun combine(a: LongArray, b: LongArray, recurrence: LongArray): LongArray {
    val length = recurrence.size
    val temporary = LongArray(2 * length - 1)

    for (i in 0 until length) {
        if (a[i] == 0L) continue
        for (j in 0 until length) {
            if (b[j] == 0L) continue
            temporary[i + j] = (temporary[i + j] + a[i] * b[j]) % MOD
        }
    }

    for (degree in temporary.lastIndex downTo length) {
        val value = temporary[degree]
        if (value == 0L) continue
        for (j in 1..length) {
            temporary[degree - j] =
                (temporary[degree - j] + value * recurrence[j - 1]) % MOD
        }
    }

    return temporary.copyOf(length)
}

private fun linearRecurrenceNth(
    initial: LongArray,
    recurrence: LongArray,
    index: Long
): Long {
    if (index < initial.size) return initial[index.toInt()]
    val length = recurrence.size
    if (length == 0) return 0L

    var result = LongArray(length)
    result[0] = 1L

    var base = LongArray(length)
    if (length == 1) {
        base[0] = recurrence[0]
    } else {
        base[1] = 1L
    }

    var exponent = index
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = combine(result, base, recurrence)
        }
        base = combine(base, base, recurrence)
        exponent = exponent shr 1
    }

    var answer = 0L
    for (i in 0 until length) {
        answer = (answer + result[i] * initial[i]) % MOD
    }
    return answer
}

fun main() {
    val scanner = FastScanner()
    val n = scanner.nextInt()
    val targetLength = scanner.nextLong()
    val words = Array(n) { scanner.next() }

    val suffixes = linkedSetOf<String>()
    for (word in words) {
        for (i in 1 until word.length) {
            suffixes.add(word.substring(i))
        }
    }

    val states = ArrayList<State>()
    val stateId = HashMap<State, Int>()

    fun addState(state: State) {
        if (state !in stateId) {
            stateId[state] = states.size
            states.add(state)
        }
    }

    addState(State(0, ""))
    for (suffix in suffixes) addState(State(1, suffix))
    for (suffix in suffixes) addState(State(2, suffix))

    val graph = Array(states.size) { ArrayList<Edge>() }

    fun getState(side: Int, residual: String): Int {
        return stateId[State(side, residual)]!!
    }

    for (top in words) {
        for (bottom in words) {
            when {
                top == bottom -> {
                    graph[0].add(Edge(0, top.length))
                }
                top.startsWith(bottom) -> {
                    val residual = top.substring(bottom.length)
                    graph[0].add(Edge(getState(1, residual), bottom.length))
                }
                bottom.startsWith(top) -> {
                    val residual = bottom.substring(top.length)
                    graph[0].add(Edge(getState(2, residual), top.length))
                }
            }
        }
    }

    for (id in 1 until states.size) {
        val state = states[id]
        val residual = state.residual
        for (word in words) {
            when {
                residual == word -> {
                    graph[id].add(Edge(0, residual.length))
                }
                residual.startsWith(word) -> {
                    val nextResidual = residual.substring(word.length)
                    graph[id].add(Edge(getState(state.side, nextResidual), word.length))
                }
                word.startsWith(residual) -> {
                    val nextResidual = word.substring(residual.length)
                    val oppositeSide = if (state.side == 1) 2 else 1
                    graph[id].add(Edge(getState(oppositeSide, nextResidual), residual.length))
                }
            }
        }
    }

    val maximumRecurrenceLength = states.size * 5
    val sampleCount = maximumRecurrenceLength * 2 + 10
    val dp = Array(sampleCount) { LongArray(states.size) }
    dp[0][0] = 1L

    for (length in 0 until sampleCount) {
        for (state in states.indices) {
            val value = dp[length][state]
            if (value == 0L) continue

            for (edge in graph[state]) {
                val nextLength = length + edge.weight
                if (nextLength >= sampleCount) continue
                var updated = dp[nextLength][edge.to] + value
                if (updated >= MOD) updated -= MOD
                dp[nextLength][edge.to] = updated
            }
        }
    }

    val sequence = LongArray(sampleCount) { dp[it][0] }
    if (targetLength < sampleCount) {
        print(sequence[targetLength.toInt()])
        return
    }

    val recurrence = berlekampMassey(sequence)
    print(linearRecurrenceNth(sequence, recurrence, targetLength))
}

