        var discrepancy = sequence[index]
        for (i in 1..length) {
            discrepancy += c[i] * sequence[index - i] % MOD
            if (discrepancy >= MOD) discrepancy -= MOD
        }

        if (discrepancy == 0L) {
            shift++
            continue
        }

        val coefficient = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD
        val previousC = c.toMutableList()

        val requiredSize = b.size + shift
        while (c.size < requiredSize) c.add(0L)

        for (i in b.indices) {
            val subtract = coefficient * b[i] % MOD
            var value = c[i + shift] - subtract
            if (value < 0) value += MOD
            c[i + shift] = value
        }

        if (2 * length <= index) {
            length = index + 1 - length
            b = previousC
            lastDiscrepancy = discrepancy
            shift = 1
        } else {
            shift++
        }
    }

    val recurrence = LongArray(length)
    for (i in 1..length) {
        recurrence[i - 1] = if (c[i] == 0L) 0L else MOD - c[i]
    }
    return recurrence
}

private fun combine(a: LongArray, b: LongArray, recurrence: LongArray): LongArray {
    val n = recurrence.size
    val product = LongArray(2 * n - 1)

    for (i in 0 until n) {
        if (a[i] == 0L) continue
        for (j in 0 until n) {
            if (b[j] == 0L) continue
            val add = a[i] * b[j] % MOD
            var value = product[i + j] + add
            if (value >= MOD) value -= MOD
            product[i + j] = value
        }
    }

    for (degree in 2 * n - 2 downTo n) {
        val value = product[degree]
        if (value == 0L) continue

        for (j in 1..n) {
            val add = value * recurrence[j - 1] % MOD
            val target = degree - j
            var updated = product[target] + add
            if (updated >= MOD) updated -= MOD
            product[target] = updated
        }
    }

    return product.copyOf(n)
}

private fun nthTerm(initial: LongArray, recurrence: LongArray, index: Long): Long {
    if (index < initial.size) return initial[index.toInt()]

    val n = recurrence.size
    if (n == 0) return 0L

    var result = LongArray(n)
    result[0] = 1L

    var base = LongArray(n)
    if (n == 1) {
        base[0] = recurrence[0]
    } else {
        base[1] = 1L
    }

    var exponent = index
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = combine(result, base, recurrence)
        }
        base = combine(base, base, recurrence)
        exponent = exponent shr 1
    }

    var answer = 0L
    for (i in 0 until n) {
        answer += result[i] * initial[i] % MOD
        if (answer >= MOD) answer -= MOD
    }
    return answer
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val targetLength = fs.nextLong()
    val words = Array(n) { fs.next() }
    val maxWordLength = words.maxOf { it.length }

    val suffixes = linkedSetOf<String>()
    for (word in words) {
        for (cut in 1 until word.length) {
            suffixes.add(word.substring(cut))
        }
    }

    val sides = mutableListOf(0)
    val residuals = mutableListOf("")
    val stateIndex = HashMap<String, Int>()

    fun stateKey(side: Int, residual: String) = "$side#$residual"

    for (suffix in suffixes) {
        val index = sides.size
        sides.add(1)
        residuals.add(suffix)
        stateIndex[stateKey(1, suffix)] = index
    }
    for (suffix in suffixes) {
        val index = sides.size
        sides.add(2)
        residuals.add(suffix)
        stateIndex[stateKey(2, suffix)] = index
    }

    val stateCount = sides.size
    val edges = Array(stateCount) { mutableListOf<Edge>() }

    fun addComparison(
        from: Int,
        first: String,
        firstSide: Int,
        second: String,
        secondSide: Int
    ) {
        val commonLength = minOf(first.length, second.length)
        for (i in 0 until commonLength) {
            if (first[i] != second[i]) return
        }

        val target = when {
            first.length == second.length -> 0
            first.length > second.length -> {
                val residual = first.substring(commonLength)
                stateIndex[stateKey(firstSide, residual)]!!
            }
            else -> {
                val residual = second.substring(commonLength)
                stateIndex[stateKey(secondSide, residual)]!!
            }
        }

        edges[from].add(Edge(target, commonLength))
    }

    for (firstWord in words) {
        for (secondWord in words) {
            addComparison(0, firstWord, 1, secondWord, 2)
        }
    }

    for (state in 1 until stateCount) {
        val residual = residuals[state]
        if (sides[state] == 1) {
            for (word in words) {
                addComparison(state, residual, 1, word, 2)
            }
        } else {
            for (word in words) {
                addComparison(state, residual, 2, word, 1)
            }
        }
    }

    val recurrenceBound = stateCount * maxWordLength
    val termCount = 2 * recurrenceBound + 5
    val dp = Array(termCount) { LongArray(stateCount) }
    dp[0][0] = 1L

    for (length in 0 until termCount) {
        for (state in 0 until stateCount) {
            val ways = dp[length][state]
            if (ways == 0L) continue

            for (edge in edges[state]) {
                val nextLength = length + edge.length
                if (nextLength >= termCount) continue

                var value = dp[nextLength][edge.to] + ways
                if (value >= MOD) value -= MOD
                dp[nextLength][edge.to] = value
            }
        }
    }

    val sequence = LongArray(termCount) { dp[it][0] }

    if (targetLength < termCount) {
        print(sequence[targetLength.toInt()])
        return
    }

    val recurrence = berlekampMassey(sequence)
    val initial = sequence.copyOf(recurrence.size)
    print(nthTerm(initial, recurrence, targetLength))
}

import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD = 998244353L

private data class Edge(val from: Int, val to: Int, val weight: Int)

private class FastScanner {
    private val reader = BufferedReader(InputStreamReader(System.`in`))
    private var tokenizer = StringTokenizer("")

    fun next(): String {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = StringTokenizer(reader.readLine())
        }
        return tokenizer.nextToken()
    }

    fun nextInt(): Int = next().toInt()
    fun nextLong(): Long = next().toLong()
}

private fun modPow(baseValue: Long, exponentValue: Long): Long {
    var base = baseValue
    var exponent = exponentValue
    var result = 1L
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = result * base % MOD
        }
        base = base * base % MOD
        exponent = exponent shr 1
    }
    return result
}

private fun compatible(a: String, b: String): Boolean {
    val length = minOf(a.length, b.length)
    for (i in 0 until length) {
        if (a[i] != b[i]) return false
    }
    return true
}

private fun berlekampMassey(sequence: LongArray): LongArray {
    var c = mutableListOf(1L)
    var b = mutableListOf(1L)
    var length = 0
    var shift = 1
    var lastDiscrepancy = 1L

    for (index in sequence.indices) {
        var discrepancy = sequence[index]
        for (i in 1..length) {
            if (i < c.size) {
                discrepancy = (discrepancy + c[i] * sequence[index - i]) % MOD
            }
        }

        if (discrepancy == 0L) {
            shift++
            continue
        }

        val oldC = c.toMutableList()
        val coefficient = discrepancy * modPow(lastDiscrepancy, MOD - 2) % MOD
        val requiredSize = b.size + shift
        while (c.size < requiredSize) c.add(0L)

        for (i in b.indices) {
            val position = i + shift
            c[position] = (c[position] - coefficient * b[i]) % MOD
            if (c[position] < 0) c[position] += MOD
        }

        if (2 * length <= index) {
            length = index + 1 - length
            b = oldC
            lastDiscrepancy = discrepancy
            shift = 1
        } else {
            shift++
        }
    }

    return LongArray(length) { i ->
        if (i + 1 < c.size && c[i + 1] != 0L) MOD - c[i + 1] else 0L
    }
}

private fun combine(a: LongArray, b: LongArray, recurrence: LongArray): LongArray {
    val length = recurrence.size
    val product = LongArray(2 * length - 1)

    for (i in 0 until length) {
        if (a[i] == 0L) continue
        for (j in 0 until length) {
            if (b[j] == 0L) continue
            product[i + j] = (product[i + j] + a[i] * b[j]) % MOD
        }
    }

    for (degree in 2 * length - 2 downTo length) {
        val value = product[degree]
        if (value == 0L) continue
        for (j in 0 until length) {
            val target = degree - 1 - j
            product[target] = (product[target] + value * recurrence[j]) % MOD
        }
    }

    return product.copyOf(length)
}

private fun linearRecurrenceNth(
    initial: LongArray,
    recurrence: LongArray,
    index: Long
): Long {
    if (index < initial.size) return initial[index.toInt()]

    val length = recurrence.size
    if (length == 0) return 0L

    var result = LongArray(length)
    result[0] = 1L

    var base = LongArray(length)
    if (length == 1) {
        base[0] = recurrence[0]
    } else {
        base[1] = 1L
    }

    var exponent = index
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) {
            result = combine(result, base, recurrence)
        }
        base = combine(base, base, recurrence)
        exponent = exponent shr 1
    }

    var answer = 0L
    for (i in 0 until length) {
        answer = (answer + result[i] * initial[i]) % MOD
    }
    return answer
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val targetLength = fs.nextLong()
    val words = Array(n) { fs.next() }

    val stateIndex = HashMap<String, Int>()
    val stateSide = ArrayList<Int>()
    val stateResidual = ArrayList<String>()

    fun addState(side: Int, residual: String): Int {
        if (side == 0) {
            if (stateSide.isEmpty()) {
                stateSide.add(0)
                stateResidual.add("")
            }
            return 0
        }
        val key = "$side#$residual"
        return stateIndex.getOrPut(key) {
            val index = stateSide.size
            stateSide.add(side)
            stateResidual.add(residual)
            index
        }
    }

    addState(0, "")
    for (word in words) {
        for (start in 1 until word.length) {
            val suffix = word.substring(start)
            addState(1, suffix)
            addState(2, suffix)
        }
    }

    val edges = ArrayList<Edge>()

    for (first in words) {
        for (second in words) {
            if (!compatible(first, second)) continue

            val weight = minOf(first.length, second.length)
            val destination = when {
                first.length == second.length -> 0
                first.length > second.length ->
                    addState(1, first.substring(second.length))
                else ->
                    addState(2, second.substring(first.length))
            }
            edges.add(Edge(0, destination, weight))
        }
    }

    var state = 1
    while (state < stateSide.size) {
        val side = stateSide[state]
        val residual = stateResidual[state]

        for (word in words) {
            if (!compatible(residual, word)) continue

            val weight = minOf(residual.length, word.length)
            val destination = when {
                residual.length == word.length -> 0
                residual.length > word.length ->
                    addState(side, residual.substring(word.length))
                else ->
                    addState(3 - side, word.substring(residual.length))
            }
            edges.add(Edge(state, destination, weight))
        }
        state++
    }

    val stateCount = stateSide.size
    val dimensionBound = stateCount * 5
    val termCount = 2 * dimensionBound + 10

    val dp = Array(termCount) { LongArray(stateCount) }
    dp[0][0] = 1L

    for (length in 1 until termCount) {
        for (edge in edges) {
            if (edge.weight > length) continue
            val value = dp[length - edge.weight][edge.from]
            if (value == 0L) continue

            var updated = dp[length][edge.to] + value
            if (updated >= MOD) updated -= MOD
            dp[length][edge.to] = updated
        }
    }

    val sequence = LongArray(termCount) { dp[it][0] }
    if (targetLength < termCount) {
        print(sequence[targetLength.toInt()])
        return
    }

    val recurrence = berlekampMassey(sequence)
    val initial = sequence.copyOf(recurrence.size)
    print(linearRecurrenceNth(initial, recurrence, targetLength))
}
